describe('Paste Image from Clipboard into Upload Area', () => {
  beforeEach(() => {
    cy.visit('/upload');
  });

  it('should successfully paste an image from the clipboard into the upload area', () => {
    // Intercept the paste event
    cy.intercept('POST', '/api/uploads/paste').as('pasteUpload');

    // Get the upload button
    cy.get('[data-testid="upload-button"]').click();

    // Paste an image from the clipboard
    cy.get('[data-testid="paste-area"]').type('data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAA...');

    // Verify the paste area contains the image data
    cy.get('[data-testid="paste-area"]').should('contain', 'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAA...');

    // Verify the upload button is still visible
    cy.get('[data-testid="upload-button"]').should('be.visible');

    // Click the upload button to initiate the upload
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the upload API call
    cy.wait('@pasteUpload');

    // Verify upload was successful
    cy.get('[data-testid="upload-success-message"]').should('be.visible');
    cy.get('[data-testid="upload-success-message"]').should('contain', 'Image uploaded successfully');
  });

  it('should handle pasting an invalid image format and display error message', () => {
    // Intercept the paste event
    cy.intercept('POST', '/api/uploads/paste').as('pasteUpload');

    // Get the upload button
    cy.get('[data-testid="upload-button"]').click();

    // Paste an invalid image format
    cy.get('[data-testid="paste-area"]').type('invalid/image/format');

    // Verify the paste area contains the invalid data
    cy.get('[data-testid="paste-area"]').should('contain', 'invalid/image/format');

    // Verify the upload button is still visible
    cy.get('[data-testid="upload-button"]').should('be.visible');

    // Click the upload button
    cy.get('[data-testid="upload-button"]').click();

    // Wait for the upload API call
    cy.wait('@pasteUpload');

    // Verify error message is displayed
    cy.get('[data-testid="upload-error-message"]').should('be.visible');
    cy.get('[data-testid="upload-error-message"]').should('contain', 'Invalid image format');
  });
});
